<div class="space-y-5 max-w-5xl"><?php include __DIR__.'/_nav.php'; ?><div><h1 class="text-xl font-semibold">Email Settings</h1><p class="text-sm text-slate-500 mt-1">Mailgun delivery, Coysh Digital branding, the shared email wrapper, and reusable images.</p></div>
<form method="POST" action="/settings/email" class="space-y-5"><?= csrfField() ?><div class="bg-white border rounded-lg p-5"><h2 class="font-medium mb-4">Mailgun</h2><div class="grid sm:grid-cols-2 gap-4"><label class="text-sm">Region<select name="region" class="mt-1 w-full border rounded px-3 py-2"><option value="eu">EU</option><option value="us" <?= ($config['region']??'eu')==='us'?'selected':'' ?>>US</option></select></label><label class="text-sm">Sending domain<input name="sending_domain" value="<?= e($config['sending_domain']??'') ?>" placeholder="mg.example.com" class="mt-1 w-full border rounded px-3 py-2"></label><label class="text-sm">Private API key<input type="password" name="api_key" placeholder="<?= !empty($config['api_key'])?'Configured — leave blank to keep':'key-…' ?>" class="mt-1 w-full border rounded px-3 py-2"></label><label class="text-sm">Webhook signing key<input type="password" name="webhook_signing_key" placeholder="<?= !empty($config['webhook_signing_key'])?'Configured — leave blank to keep':'Signing key' ?>" class="mt-1 w-full border rounded px-3 py-2"></label></div></div>
<div class="bg-white border rounded-lg p-5"><h2 class="font-medium mb-4">Delivery and brand</h2><div class="grid sm:grid-cols-2 gap-4"><label class="text-sm">From name<input name="from_name" value="<?= e($config['from_name']??'') ?>" class="mt-1 w-full border rounded px-3 py-2"></label><label class="text-sm">From email<input type="email" name="from_email" value="<?= e($config['from_email']??'') ?>" class="mt-1 w-full border rounded px-3 py-2"></label><label class="text-sm">Reply-to<input type="email" name="reply_to" value="<?= e($config['reply_to']??'') ?>" class="mt-1 w-full border rounded px-3 py-2"></label><label class="text-sm">Brand colour<input type="color" name="brand_colour" value="<?= e($config['brand_colour']??'#a1c63e') ?>" class="mt-1 block h-10 w-16 border rounded"></label><label class="text-sm sm:col-span-2">Header logo URL<input name="logo_url" value="<?= e($config['logo_url']??'/coysh-digital-email-logo.png') ?>" class="mt-1 w-full border rounded px-3 py-2"><span class="block mt-1 text-xs text-slate-400">Root-relative or HTTPS. The Coysh Digital logo is used by default.</span></label><label class="text-sm">Business name<input name="business_name" value="<?= e($config['business_name']??'') ?>" class="mt-1 w-full border rounded px-3 py-2"><span class="block mt-1 text-xs text-slate-400">Displayed compactly in the email footer.</span></label><label class="text-sm">Privacy URL<input type="url" name="privacy_url" value="<?= e($config['privacy_url']??'') ?>" class="mt-1 w-full border rounded px-3 py-2"></label><label class="text-sm sm:col-span-2">Business address<textarea required name="business_address" rows="3" class="mt-1 w-full border rounded px-3 py-2"><?= e($config['business_address']??'') ?></textarea><span class="block mt-1 text-xs text-slate-400">Displayed with the unsubscribe link in the email footer.</span></label><div class="flex gap-4"><label class="text-sm"><input type="checkbox" name="tracking_opens" <?= !isset($config['tracking_opens'])||$config['tracking_opens']?'checked':'' ?>> Default open tracking</label><label class="text-sm"><input type="checkbox" name="tracking_clicks" <?= !isset($config['tracking_clicks'])||$config['tracking_clicks']?'checked':'' ?>> Default click tracking</label></div></div></div>
<div class="bg-white border rounded-lg p-5"><div class="flex flex-wrap justify-between gap-3"><div><h2 class="font-medium">Master HTML</h2><p class="text-sm text-slate-500 mt-1">Shared wrapper used by every template and campaign. Content is frozen into a campaign when it is scheduled.</p></div><button type="button" id="restore-master-html" class="px-3 py-2 border rounded text-sm">Restore Coysh default</button></div><textarea id="master-html" name="master_html" rows="20" spellcheck="false" class="mt-4 w-full border rounded px-3 py-2 font-mono text-xs"><?= e($config['master_html']??CoyshCRM\Services\EmailRenderer::defaultMasterHtml()) ?></textarea><p class="text-xs text-slate-400 mt-2">Required: <code>{{logo}}</code>, <code>{{content}}</code>, <code>{{footer}}</code>. Available theme values: <code>{{background_colour}}</code>, <code>{{body_colour}}</code>, <code>{{text_colour}}</code>, <code>{{accent_colour}}</code>, <code>{{font}}</code>, <code>{{width}}</code>, and <code>{{preheader}}</code>.</p></div>
<button class="px-4 py-2 bg-accent-600 text-white rounded text-sm">Save settings</button></form>
<script>document.getElementById('restore-master-html').addEventListener('click',()=>{if(confirm('Replace the current Master HTML with the Coysh Digital default?'))document.getElementById('master-html').value=<?= json_encode(CoyshCRM\Services\EmailRenderer::defaultMasterHtml(),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>});</script>
<div class="bg-white border rounded-lg p-5"><h2 class="font-medium mb-2">Readiness</h2><p class="text-sm text-slate-500">APP_URL: <code><?= e(appUrl()) ?></code></p><p class="text-sm text-slate-500">Last verified: <?= e($config['last_verified_at']??'Never') ?> · Worker last ran: <?= e($config['worker_last_run_at']??'Never') ?></p><div class="flex gap-2 mt-4"><form method="POST" action="/settings/email/verify"><?= csrfField() ?><button class="px-3 py-2 border rounded text-sm">Verify Mailgun domain</button></form><form method="POST" action="/settings/email/webhooks"><?= csrfField() ?><button class="px-3 py-2 border rounded text-sm">Configure webhooks</button></form></div><p class="text-xs text-slate-400 mt-3">Configure Mailgun's sending and tracking DNS records separately, then run the worker every minute.</p></div>
<div class="bg-white border rounded-lg p-5"><h2 class="font-medium mb-3">Email images</h2><form method="POST" enctype="multipart/form-data" action="/settings/email/assets" class="flex flex-wrap gap-2 items-end"><?= csrfField() ?><label class="text-sm">JPEG, PNG, or GIF<input required type="file" name="asset" accept="image/jpeg,image/png,image/gif" class="block mt-1"></label><label class="text-sm">Default alt text<input name="alt_text" class="mt-1 border rounded px-3 py-2"></label><button class="px-3 py-2 border rounded text-sm">Upload</button></form><?php if($assets): ?><div class="grid grid-cols-3 sm:grid-cols-5 gap-3 mt-4"><?php foreach($assets as $a): ?><div><img src="/email/assets/<?= e($a['public_token']) ?>/<?= rawurlencode($a['original_name']) ?>" alt="<?= e($a['alt_text']) ?>" class="aspect-square object-cover rounded border"><p class="text-xs truncate mt-1"><?= e($a['original_name']) ?></p></div><?php endforeach ?></div><?php endif ?></div>
</div>
